"""Review artifacts generated by the actual application renderer, using fictional data."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT.parents[1] / "central" / "backend"))
from app.services import report_m53 as m53
from build_source_structure import records

out = ROOT / "runtime-review"
out.mkdir(exist_ok=True)
for name, record in records().items():
    name = name.replace("source", "runtime")
    docx, pdf, layout = m53.render_documents(record["values"],
        [{"answer": text} for text in record["statements"]], record["confirmations"],
        preview=True, blank=record["kind"] == "blank")
    (out / f"{name}.docx").write_bytes(docx)
    (out / f"{name}.pdf").write_bytes(pdf)
    (out / f"{name}.layout.json").write_text(json.dumps(layout, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"{name}: {len(layout['pages'])} pages")
